{
  "justification": "Issue salience is dominated by health/NHS, economy/costs, and immigration, while BES scales indicate a moderately authoritarian tilt (6.2/10), a mild lean toward redistribution (4.68/10), and EU integration slightly below midpoint (4.73/10). This supports strong Care, notable Authority and Loyalty (national cohesion) components, moderate Equality, with little clear evidence on Sanctity or Proportionality direction.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "Ipsos: NHS/Healthcare (41%), Ageing population/Social care (6%), Poverty/Inequality (12%), Mental health (2%), Inflation/Prices (29%); BES: Health salience (7%), Living costs (19.7%).",
      "status": "SCORED",
      "weight": 0.4
    },
    {
      "foundation": "loyalty",
      "basis": "Ipsos: Immigration (30%), Defence/Foreign affairs (12%); BES: War (2%), European integration self-placement 4.73 (slightly below midpoint).",
      "status": "SCORED",
      "weight": 0.15
    },
    {
      "foundation": "authority",
      "basis": "BES authority–liberty mean 6.2 (more authoritarian); Ipsos: Crime/Law and order (10%), Defence/Foreign affairs (12%).",
      "status": "SCORED",
      "weight": 0.25
    },
    {
      "foundation": "sanctity",
      "basis": "Ipsos: Pollution/Environment/Climate change (9%), Morality/Individual behaviour/Lifestyle (2%), Drug abuse (1%); BES: Morals (0.3%), Gender/sexuality/family (0.1%).",
      "status": "AMBIGUOUS",
      "weight": null
    },
    {
      "foundation": "equality",
      "basis": "Ipsos: Poverty/Inequality (12%), Low pay/Minimum wage (5%), Pensions/Benefits (4%); BES redistribution mean 4.68 (mildly pro-redistribution).",
      "status": "SCORED",
      "weight": 0.2
    },
    {
      "foundation": "proportionality",
      "basis": "Ipsos: Taxation (7%); BES: Welfare (0.4%), Debt/deficit (0.2%)—no clear attitudes on merit-based reward or deservingness.",
      "status": "INSUFFICIENT",
      "weight": null
    }
  ]
